input.command:
cd /workspace && cp -r src /tmp/src_before && cat > src/money.ts <<'EOF'
export function formatAmount(cents: number): string {
  const sign = cents < 0 ? '-' : '';
  const absolute = Math.abs(cents);
  return sign + Math.floor(absolute / 100) + '.' + String(absolute % 100).padStart(2, '0');
}
EOF
cat > src/invoice.ts <<'EOF'
import { formatAmount } from './money';
export function renderInvoice(id: string, cents: number): string { return id + ': $' + formatAmount(cents); }
EOF
cat > src/report.ts <<'EOF'
import { formatAmount } from './money';
export function renderReport(rows: { id: string; cents: number }[]): string {
  return rows.map(row => row.id + ',' + formatAmount(row.cents)).join('\n');
}
EOF
rm src/invoiceAmount.ts src/reportAmount.ts
grep -rn "invoiceAmount\|reportAmount" src checks || echo "no old references"
cat >> checks/public.cjs <<'EOF'

const { formatAmount } = require('../.build/money');
assert.equal(formatAmount(0), '0.00');
assert.equal(formatAmount(5), '0.05');
assert.equal(formatAmount(123), '1.23');
assert.equal(formatAmount(-1), '-0.01');
assert.equal(formatAmount(-250), '-2.50');
assert.equal(formatAmount(-0), '0.00');
EOF
rm -rf .build && npx --no-install tsc -p tsconfig.json 2>/dev/null || tsc -p tsconfig.json; node checks/public.cjs && echo PASS
# compare outputs against original implementation for a range of values
node -e '
const ts=require("child_process");
' ; cd /tmp && rm -rf ob && mkdir ob && cp -r /tmp/src_before ob/src && cp /workspace/tsconfig.json ob/ && cd ob && tsc -p tsconfig.json && cd /workspace && node -e '
const o=require("/tmp/ob/.build/invoice"), r=require("/tmp/ob/.build/report");
const n=require("/workspace/.build/invoice"), nr=require("/workspace/.build/report");
let bad=0;
for(let c=-100000;c<=100000;c++){ if(o.renderInvoice("x",c)!==n.renderInvoice("x",c)) bad++; }
const rows=[];for(let c=-1000;c<=1000;c++)rows.push({id:"r"+c,cents:c});
if(r.renderReport(rows)!==nr.renderReport(rows)) bad++;
console.log("mismatches:",bad);'

